const e={common:{skip:"Skip intro",explore:"Explore",nextChapter:"Next chapter",endStory:"Unlock the gift",startNow:"Start now"},intro:{line1:"A journey, three stops.",line2:"Get ready to discover where",line3:"the Pasticcino Bag World Tour",line4:"Italian Roots begins.",soundTutorial:"Activate sound for a better experience.","modal-ticket":{tutorial:"Explore every chapter and receive a special gift."}},ui:{soundOn:"Enable sound",soundOff:"Disable sound",menuOpen:"Open menu",menuClose:"Close menu",modalOpen:"Open additional information",modalClose:"Close additional information",subtitlesOn:"Enable subtitles",subtitlesOff:"Disable subtitles",audioPlay:"Play audio",audioPause:"Pause audio",audioReplay:"Replay audio",mainMenu:"Main menu",lockedChapter:"Locked chapter"},chapter:{label:"Chapter","01":{onboarding:{title:"Where the Pasticcino Bag textiles are born",description:"Explore the environment and patterns. Discover the inspiration."},disclaimer:"*All fabrics' rights belong to Fondazione Lisio",patterns:{1:{namePart1:"Masaccio",namePart2:"",description:"The Masaccio velvet draws on the motifs of Renaissance cut velvet, reinterpreting its essential forms in a refined interplay of texture and movement."},2:{namePart1:"Vetrata",namePart2:"Gallone",description:"The Vetrata Gallone velvet is inspired by Gothic stained-glass windows, translating their geometry into a rich and decorative motif. Its warm, deep tones enhance the relief of the design, creating a refined interplay of light and shadow."},3:{namePart1:"Vetrata",namePart2:"Gallone",description:"The Vetrata Gallone velvet, in its tone-on-tone version, interprets the Gothic-inspired motif with a softer, more luminous effect. The light nuances enhance the velvet texture, adding depth with elegant subtlety."},4:{namePart1:"Arte",namePart2:"del Cambio",description:"The Arte del Cambio velvet is inspired by the gold coins that symbolized the Florentine guild of the same name, reinterpreted as a geometric pattern of circles on a velvet background."},5:{namePart1:"Riganna",namePart2:"",description:"The Riganna velvet is inspired by the green serpentine marble decorations of Tuscan architecture, translating their two-tone rhythm into an elegant textile motif."},6:{namePart1:"Cubo",namePart2:"Louis",description:"The Cubo Louis velvet motif references the perspective play inspired by the designs that decorated the reveals in Renaissance architecture."}},modal:{subtitle:"A journey through the",title:"Fondazione Lisio",intro:"Entering Fondazione Arte della Seta Lisio means stepping into an archive where design takes shape and becomes fabric.",body1:"For this stop of the Pasticcino Bag World Tour Italian Roots, Weekend Max Mara explored the archive of Fondazione Arte della Seta Lisio in search of patterns designed to capture the aesthetic of Tuscany.",caption1:"Renaissance ceilings, geometric decorations, mosaics and stained-glass windows.",sectionTitle:"WEEKEND MAX MARA AND TEAM LISIO",caption2:"Textile Archive of Fondazione Lisio",body2:" Many of the historic designs preserved by the foundation stem from the observation of architecture: coffered ceilings, mosaic floors, Gothic stained-glass windows and decorative motifs spanning centuries of Italian art. Elements originally conceived for stone or buildings are thus transformed into geometric modules and textile rhythms.",caption3:"Textile inspiration at Fondazione Lisio, Florence.",body3:"For the Pasticcino Bag World Tour Italian Roots project, some of these patterns were reinterpreted in broccatello, a technique that combines silk, cotton and linen to create lightweight yet three-dimensional surfaces."}},"02":{onboarding:{title1:"Where",title2:"the material",title3:"takes shape",description:"Work the marble and",description2:"create the boule."},interaction:{topArcText:"Hold down",bottomArcText:"to carve"},final:{title:"The boules",subtitle:"You're there! Here they are."},modal:{subtitle:"Boules",title:"The Marble Quarry",intro:"Budri is an Italian atelier specializing in the artistic craftsmanship of marble, quartzite, onyx and natural stone.",body1:"For the Italian Roots Special Edition, Weekend Max Mara chose to introduce a material deeply connected to Italian visual culture into the collection: marble.",caption1:"A material to interpret and transform.",sectionTitle:"WEEKEND MAX MARA AND BUDRI ATELIER",caption2:"The Essence of Marble.",body2:"The spheres that define the bag’s clasp are crafted from some of the most representative stones of Italian architecture. These include Bianco Carrara and Bardiglio, Tuscan marbles with grey veining; Verde Alpi, sourced from the historic quarries of Gressoney; Fior di Pesco, with its warm, nuanced tones; the precious Ligurian Nero Portoro, with its golden veining; together with Calacatta and black marble.",caption3:"Marble craftsmanship at Budri Marmi",body3:"From slabs of stone, small blocks are cut and progressively worked until they become perfectly polished spheres. Through this process, materials that for centuries shaped Italian basilicas, piazzas and sculptures are reinterpreted on a new scale, becoming a design detail of the Pasticcino Bag."}},"03":{onboarding:{title1:"Where the",title2:"Pasticcino Bag",title3:"comes to life",description:"Complete the three steps",description2:"and create the Pasticcino Bag."},interaction:{scissors:{title:"Pattern cutting",description:"Drag the scissors to cut it out.",cta:"Drag here"},pen:{title:"The clutch closure",description:"Drag the cursor to glue it in place."},boules:{title:"Position the boule",description:"Drag the boule to secure it.",cta:"Drag here"}},final:{title1:"the",title2:"Pasticcino Bag",subtitle:"Voila! Here it is.",cta:"Drag"}},outro:{line1:"You've discovered the places where the Pasticcino Bag World Tour Italian Roots begins.",line2:"Now it's time to explore the collection.",line3:"Come with us to Florence!"},gift:{cta:"Discover now",restart:"Restart",share:"Share"}},modal:{close:"Close"},leadForm:{ariaLabel:"Receive your gift — Registration form",title:{line1:"Become a",line2:"Weekender!"},intro:"Ready to set off with Pasticcino Bag? Fill in your details to receive your digital gift by email.",success:"Perfect ! Your request has been received.",successScreen:{title:{line1:"There is a",line2:"Gift for you"},subtitle:"Check your email!"},fields:{name:"Name",surname:"Surname",email:"Email",emailLabel:"name{'@'}email.com",phoneLabel:"Phone number (optional)",phone:"Phone",phonePrefix:"Prefix",dobLabel:"Date of birth (optional)",dobDay:"Day",dobMonth:"Month",dobYear:"Year"},consents:{privacyInfoPrefix:"If you want to know how we process personal data,",privacyInfoLink:"click here",intro:"With my consent you will be able to use my data, directly or with the assistance of related companies and/or your partners who act following your instructions, for the purpose of:",marketing:"Send me (by post, email, SMS, MMS, telephone and other digital communication channels) newsletters, invitations to events, surveys and market research, commercial and advertising communications, promotions, discounts and information on other initiatives regarding your products and services that may be of interest to me, based on the preferences expressed during visits of your websites and/orduring any purchases and contacts with you (for example in the case of participation in events, use of customer service services or surveys)",profiling:"Send me the aforementioned communications (by post, email, SMS, MMS, telephone and other digital communication channels) without personalizing them.",yes:"Yes",no:"No",privacyPrefix:"Please read carefully our privacy notice on the processing of personal data",privacyLink:"here",privacyUrl:"http://weekendmaxmara.com/info/site-info/privacy-policy/?r=0",privacySuffix:"",privacyRequired:"You must accept the privacy policy to continue."},validation:{required:"This field is required",email:"Please enter a valid email address",phone:"Please enter a valid phone number",date:"Please enter a valid date",personalName:"Please use letters, spaces, apostrophes or hyphens only",length:"Too long",incomplete:"Sorry, not all fields are filled out correctly."},cta:{submit:"Receive now!",skip:"Skip"},errors:{network:"A network error occurred. Check your connection and try again.",server:"An error occurred. Please try again in a few moments."},subscribed:{title:{line1:"RECEIVE YOUR",line2:"GIFT!"},paragraph1:"Dear Weekender, you've made it this far along the Italian Roots World Tour, following the path through stories, places, and memories that connect past and present.",paragraph2:"A special gift has been set aside just for you along the way. A small surprise to celebrate your journey.",privacyText:"If you want to know how we process your personal data,",privacyLink:"click here"},privacyPolicy:{title:"Privacy Policy",close:"Close",body:["We hereby provide you with some information on the processing of your personal data, mainly using electronic means. Max Mara Fashion Group S.r.l. with registered address in Via Pietro Giannone, 10 - 10122 Turin (Italy) acts as Data Controller, in accordance with the General Data Protection Regulation (EU) 2016/679.","We may use and disclose the personal data that you have feely provided us also to third parties in Europe duly appointed as Data Processors [in order to send your digital stickers related to the Pasticcino World Tour - Spanish Heritage - FW25 campaign to the email address provided]. We confirm that all appropriate measures have been duly undertaken to properly protect your personal data, which will be retained on the servers of a duly appointed Data Processor, for as long as necessary for the purposes described in this notice and in any case for no more than 30 days following the email you receive. In the event of any transfer of data to third countries with legislation other than European legislation, we take measures to ensure that this is done in compliance with European legislation, including the adoption of Standard Contractual Clauses, where applicable. After that period your personal data will be securely deleted. We would like to remind you that if you have already given or give your specific consent/s for Max Mara Fashion Group S.r.l.'s CRM purposes, your data may be processed by the latter as provided for in its Privacy Policy weekendmaxmara.com/info/site-info/privacy-policy/?r=0 and in compliance with the consent/s given therein.","You may access your personal data free of charge, request that your personal data be updated, amended or deleted or exercise any other rights under the applicable data protection law by sending an email at infoprivacy@weekendmaxmara.com or regular mail at the address appearing above, at any time and free of charge. You also have the right to lodge a complaint with the here (www.garanteprivacy.it) or the supervisory authority in the EU Member State where you usually live or work. We inform you that we, as Data Controller, have duly appointed our Data Protection Officer who can be contacted at the following addresses: Via Pietro Giannone 10 –10121 Turin (Italy); email: dpo@mmfg.it"]}},subscribedForm:{ariaLabel:"Receive your gift — Registration form",title:"Receive your gift",description:{block1:"Dear Weekender, your journey through the fifth stop of the Pasticcino Bag World Tour has led you through stories, places and memories where past and present meet. Along the way, we kept a special gift just for you.",block2:"A small surprise to celebrate this journey."}},stages:{intro:{title:"Intro"},chapter01:{title:"The Archive\nof Textiles"},chapter02:{title:"The Marble\nQuarry"},chapter03:{title:"Crafting in\nSan Miniato"},outro:{title:"Outro"},gift:{title:"Buchette"}},chapterTitle:{1:{rows:[["The","Archive"],["of","Textiles"]]},2:{rows:[["The","Marble"],["Quarry"]]},3:{rows:[["Crafting in"],["San"],["Miniato"]]}}};export{e as default};
